(function(){
var XB='';try{XB=XC_base()}catch(eB){}
if(!XB){try{XB=XC_ok(source.get('xcLine'))}catch(eB2){}}
if(!XB)XB='https://quickapi.biduwenxue.com';
function CV(c){c=String(c||'');if(!c||c==='null'||c==='undefined')return '';
  if(c.indexOf('http')===0)return c;
  return 'https://biduwenxue-img.oss-cn-beijing.aliyuncs.com/'+c.replace(/^\/+/, '');}
var o={};try{o=JSON.parse(String(result||''))}catch(e){o={}}
var d=o.data, arr=[], i, j;
if(d && typeof d.length==='number' && d.length>0){
  if(d.length && d[0] && d[0].dataList){          // 精品 columnContent：摊平各栏目 dataList
    for(i=0;i<d.length;i++){var dl=d[i].dataList||[];for(j=0;j<dl.length;j++)arr.push(dl[j])}
  }else arr=d;                                    // 榜单 rankBookList
}else if(d && d.pageList && d.pageList.length){arr=d.pageList}  // 分类 search/lib
else if(d && d.pageList){arr=d.pageList}
else if(o.pageList){arr=o.pageList}
var out=new Packages.java.util.ArrayList();
for(i=0;i<arr.length;i++){
  var b=arr[i]||{};if(!b)continue;
  var bid=b.id||b.bookId;if(!bid)continue;
  var cn=b.categoryname||b.categoryName||'';
  var wc=b.wordcount||b.wordCount||'';
  var au=b.authorname||b.authorName||b.author||'';
  var gr=b.bookGrade||'';
