@js:
sort = [];
push = (title, url, type) => sort.push({
    title: title,
    url: url,
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: type
    }
});
$$ = tagId => `https://m.music.migu.cn/migumusic/h5/playlist/list?columnId=15127272&tagId=${tagId}&pageNum={{page}\}&pageSize=20`;




push("༺ 推荐 ༻",null,1);
push("最新",$$(""),0.25);
push("推荐","https://m.music.migu.cn/migumusic/h5/home/songlist",0.25);
push("热门","https://m.music.migu.cn/migumusic/h5/playlist/list?columnId=38199588&pageNum={{page}\}&pageSize=12",0.25);


JSON.parse(java.ajax("https://m.music.migu.cn/migumusic/h5/playlist/allTag")).data.tags.map($=>{
	push("༺ "+$.tagName+" ༻",null,1);
	$.tags.map($=>push($.tagName,$$($.tagId),0.25));
});


JSON.stringify(sort);

