var FQ_TC = "D在主特家军然表场4要只v和#6别还g现儿岁##此象月3出战工相o男直失世F都平文什VO将真T那当#会立些u是十张学气大爱两命全后东性通被1它乐接而感车山公了常以何可话先pi叫轻M士w着变尔快l个说少色里安花远7难师放t报认面道S#克地度I好机U民写把万同水新没书电吃像斯5为y白几日教看但第加候作上拉住有法r事应位利你声身国问马女他Y比父xAHNsX边美对所金活回意到z从j知又内因点Q三定8Rb正或夫向德听更#得告并本q过记L让打f人就者去原满体做经K走如孩cG给使物#最笑部#员等受k行一条果动光门头见往自解成处天能于名其发总母的死手入路进心来h时力多开已许d至由很界n小与Z想代么分生口再妈望次西风种带J#实情才这#E我神格长觉间年眼无不亲关结0友信下却重己老2音字m呢明之前高PB目太e9起棱她也W用方子英每理便四数期中C外样a海们任";
var FQ_TL = "体y十现快便话却月物水的放知爱万#表风理O老也p常克平几最主她s将法情o光a我呢J员太每望受教w利军已U人如变得要少斯门电m男没AK国时中走么何口小向问轻Td神下间车fG度D又大面远就写j给通起实E#它去S到道数吃们加P是无把事西多界#发新外活解孩只作前Y尔经#u心告父等Q民全这9果安#i母8r说任先和地C张战场g像cq你使#样总目x性处音头#应乐关能花l当名手4重字声力友然生代内里本回真入师象#0点R亲V种动英命ZhX做特边高有B为期自年马认出接至H正方感所明者棱F住学还分意更其n但比觉以由死家让失士L2I金叫身报听W再原山海白很见5直位第工个开岁好用都于可同3次四#日信与女笑满并部什不从或机此#了记三e些bN夫会才儿眼两美被一公来立z长对己看k许因相色后往打结格过世气7子条在书之定v拉成进带着东上想天他妈1文而路那别德6Mt行候难";
function fqDec(s, t) {
  if (s == null) return "";
  s = String(s);
  var out = [], i, c, ch;
  for (i = 0; i < s.length; i++) {
    c = s.charCodeAt(i);
    if (c >= FQ_BASE && c < FQ_BASE + t.length) {
      ch = t.charAt(c - FQ_BASE);
      out.push(ch == "#" ? s.charAt(i) : ch);
    } else out.push(s.charAt(i));
  }
  return out.join("");
}
function fqDecC(s) { return fqDec(s, FQ_TC); }
function fqDecL(s) { return fqDec(s, FQ_TL); }
function fqHasPua(s) { return /[\uE000-\uF8FF]/.test(String(s)); }
function fqFilter(info) {
  var m = {};
  try { if (info != null && String(info) != "") m = JSON.parse(String(info)) || {}; } catch (e) { m = {}; }
  var a = String(m["状态"] || ""), b = String(m["字数"] || "").replace(/\s/g, ""), c = String(m["排序"] || "");
  var st = /完/.test(a) ? 0 : (/连/.test(a) ? 1 : -1);
  var wc = -1;
  if (/^30(万)?(字)?以下/.test(b)) wc = 0;
  else if (/^30[-~～至]50/.test(b)) wc = 1;
  else if (/^50[-~～至]100/.test(b)) wc = 2;
  else if (/^100[-~～至]200/.test(b)) wc = 3;
  else if (/^200(万)?(字)?以上/.test(b)) wc = 4;
  var so = /新/.test(c) ? 1 : (/字/.test(c) ? 2 : 0);
  return "&creation_status=" + st + "&word_count=" + wc + "&sort=" + so;
}
function fqWan(n) { n = Number(n) || 0; return n >= 10000 ? (n / 10000).toFixed(1) + "万字" : n + "字"; }
function fqContent(html) {
  html = String(html);
  var m = html.match(/__INITIAL_STATE__\s*=\s*(\{[\s\S]*?\});\s*\}\s*\)\s*\(\s*\)/);
  if (!m) return "【番茄】未找到章节数据（页面结构可能已变化）";
  var st = JSON.parse(m[1].replace(/:\s*undefined/g, ":null"));
  var cd = (st.reader && st.reader.chapterData) || {};
  var raw = String(cd.content || "");
  var paras = [];
  raw.replace(/<p[^>]*>([\s\S]*?)<\/p>/g, function (a, b) { paras.push(b); return a; });
  if (!paras.length) paras = raw.split(/<br\s*\/?>|\n/);
  var lines = [], i, t;
  for (i = 0; i < paras.length; i++) {
    t = fqDecC(paras[i]).replace(/<[^>]+>/g, "").replace(/&nbsp;/g, " ").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, "\"").replace(/&#39;/g, "'").replace(/&amp;/g, "&").replace(/^\s+|\s+$/g, "");
    if (t) lines.push(t);
  }
  var text = lines.join("\n");
  var words = Number(cd.chapterWordNumber) || 0;
  if ((cd.isChapterLock === true || String(cd.isChapterLock) == "true") && words > 0 && text.length < words * 0.6) {
    text += "\n\n【未登录：番茄网页端第10章以后只返回片段。请在书源「登录」界面点「网页登录」登录自己的番茄账号，然后刷新本章。】";
  }
  if (fqHasPua(text)) text += "\n\n【番茄字体映射可能已更新，部分文字无法解码，请反馈更新书源】";
  return text;
}

